-- Campagnes v3 (20/10) : par entreprise (conseil généraliste, spécialiste, QA), prise d'actu, jamais de process.
-- Les tuiles précédentes (sauf « Relances en cours ») sont archivées, pas supprimées : leur message reste en base.
update public.campaigns set archived = true, updated_at = now() where preset in ('pepites', 'jamais', 'relance_campagne', 'repris', 'pepites_wefiit') and not archived;
on conflict (preset) do nothing;
